import products from './products.json' with {type:'json'};

const TOOL_NAME = 'inventory_search';

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description:
        'Search the product inventory by name. Matches product names case-insensitively and returns up to `limit` results.',
      inputSchema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          query: {
            type: 'string',
            description: 'Search text matched case-insensitively against product names.'
          },
          limit: {
            type: 'integer',
            minimum: 1,
            maximum: 10,
            description: 'Maximum number of results to return (1-10). Optional.'
          }
        },
        required: ['query']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, limit } = args;
  const allowed = new Set(['query', 'limit']);
  const extras = Object.keys(args).filter((k) => !allowed.has(k));
  if (extras.length) {
    throw new Error(`Invalid arguments: unknown property ${extras[0]}`);
  }

  if (query === undefined) {
    throw new Error('Invalid arguments: query is required');
  }
  if (typeof query !== 'string') {
    throw new Error('Invalid arguments: query must be a string');
  }

  if (limit !== undefined) {
    if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('Invalid arguments: limit must be an integer between 1 and 10');
    }
  }

  const needle = query.toLowerCase();
  const matches = products.filter((p) =>
    String(p.name).toLowerCase().includes(needle)
  );
  const limited = limit !== undefined ? matches.slice(0, limit) : matches;

  const text = limited.length
    ? limited.map((p) => p.name).join('\n')
    : 'No matching products found.';

  return {
    content: [{ type: 'text', text }]
  };
}

